import{_ as r,y as d,a as s,o as t,a6 as o,c as i,w as a,I as l,D as c,a7 as u}from"./chunks/framework.CJDy2q7X.js";const k=JSON.parse('{"title":"Configuration (Admin)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/admin/configuration.md","filePath":"api/workflows/admin/configuration.md","lastUpdated":1786429091000}'),h={name:"api/workflows/admin/configuration.md"};function g(p,e,f,m,w,v){const n=d("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="configuration-admin" tabindex="-1">Configuration (Admin) <a class="header-anchor" href="#configuration-admin" aria-label="Permalink to &quot;Configuration (Admin)&quot;">​</a></h1><p>The store&#39;s flat key/value settings — everything under <strong>Configuration</strong> in the admin (general, catalog, sales, customer, email, payment, shipping, …). Unlike the rest of the admin API, Configuration is <strong>not one endpoint per screen</strong>: its schema is registered at runtime by every installed package, so the API exposes <strong>three generic endpoints</strong> that work across any current or future section. Everything is keyed by a <strong>slug</strong> — a dotted section path like <code>sales.order_settings</code> or <code>general.content</code>.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Integration token</strong> — ask the user; send as <code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code>. Needs the configuration permission (else <code>403</code>).</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="the-three-endpoints" tabindex="-1">The three endpoints <a class="header-anchor" href="#the-three-endpoints" aria-label="Permalink to &quot;The three endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>REST</th><th>GraphQL field</th></tr></thead><tbody><tr><td>Menu (schema)</td><td><a href="/api/rest-api/admin/configuration/menu.html">GET configuration/menu</a></td><td><code>menuAdminConfigurationMenu</code></td></tr><tr><td>Slugs (discovery)</td><td><a href="/api/rest-api/admin/configuration/slugs.html">GET configuration/slugs</a></td><td><code>listAdminConfigurationSlug</code></td></tr><tr><td>Values</td><td><a href="/api/rest-api/admin/configuration/values.html">GET configuration?slug=…</a></td><td><code>valuesAdminConfigurationValues</code></td></tr><tr><td>Update</td><td><a href="/api/rest-api/admin/configuration/update.html">POST configuration</a></td><td><code>createAdminConfigurationUpdate</code></td></tr></tbody></table><h2 id="flow-schema-→-values-→-update" tabindex="-1">Flow: schema → values → update <a class="header-anchor" href="#flow-schema-→-values-→-update" aria-label="Permalink to &quot;Flow: schema → values → update&quot;">​</a></h2>',7)),(t(),i(u,null,{default:a(()=>[c(n,{id:"mermaid-88",class:"mermaid",graph:"flowchart%20TD%0A%20%20menu%5BGET%20configuration%2Fmenu%3Cbr%2F%3Esection%2Fgroup%2Ffield%20tree%5D%20--%3E%20vals%5BGET%20configuration%3Fslug%3Dsection.group%3Cbr%2F%3Ecurrent%20values%20map%5D%0A%20%20vals%20--%3E%20form%5BRender%20form%20pre-filled%20from%20values%5D%0A%20%20form%20--%3E%20upd%5BPOST%20configuration%3Cbr%2F%3Eslug%20%2B%20values%20map%5D%0A%20%20upd%20--%3E%20back%5BReturns%20freshly-resolved%20values%3Cbr%2F%3Ere-render%2C%20no%20follow-up%20GET%5D%0A"})]),fallback:a(()=>e[0]||(e[0]=[l(" Loading... ",-1)])),_:1})),e[2]||(e[2]=o('<ul><li><strong>Menu</strong> returns the whole tree (sections → groups → fields), each field with its <code>code</code>, <code>type</code>, <code>title</code>, default, validation, and whether it&#39;s channel-/locale-based — build the config nav AND know which input control each field needs. <code>?slug=&lt;section&gt;</code> scopes to one node; <code>?include_values=true</code> (+ <code>?channel=</code>/<code>?locale=</code>) embeds values so one call renders a populated form.</li><li><strong>Slugs</strong> lists every registered slug so you can discover what to pass to Values/Update without trial-and-error.</li><li><strong>Values</strong> returns a flat <code>{ dottedCode: stringValue }</code> map for a slug (falling back to each field&#39;s default). <strong>The slug is required</strong> — the endpoint refuses to dump the whole table.</li><li><strong>Update</strong> writes a <code>values</code> map for a slug and returns the freshly-resolved values.</li></ul><h2 id="field-types-→-controls" tabindex="-1">Field types → controls <a class="header-anchor" href="#field-types-→-controls" aria-label="Permalink to &quot;Field types → controls&quot;">​</a></h2><p><code>boolean</code> → toggle · <code>select</code>/<code>multiselect</code> → dropdown(s) from the field&#39;s options · <code>text</code>/<code>textarea</code>/<code>password</code> → inputs · <code>image</code>/<code>file</code> → upload · <code>color</code> → colour picker · <code>type: &quot;custom&quot;</code> (<code>customView</code>) → <strong>read-only over the API</strong> (route the user to the admin panel).</p><p><strong>Channel- / locale-based fields</strong> vary per storefront context — add channel/locale switchers, and pass the matching <code>?channel=</code>/<code>?locale=</code> (or <code>channel</code>/<code>locale</code> keys in the update body) on read and write.</p><h2 id="two-hard-rules-when-writing-config" tabindex="-1">Two hard rules when writing config <a class="header-anchor" href="#two-hard-rules-when-writing-config" aria-label="Permalink to &quot;Two hard rules when writing config&quot;">​</a></h2><ol><li><strong>Every key must start with the slug.</strong> On update, every key in <code>values</code> must be prefixed with that request&#39;s <code>slug.</code> (slug <code>sales.order_settings</code> → keys like <code>sales.order_settings.reorder.admin</code>). The server <strong>refuses any key that escapes the slug</strong> (<code>400</code>) — this prevents overwriting an unrelated section. Build keys from the slug you&#39;re editing, never a hand-typed path.</li><li><strong>File/image fields are REST-only.</strong> Config <code>image</code>/<code>file</code> fields upload via a <strong>multipart</strong> <code>POST /api/admin/configuration</code> with the file in the <code>values[&lt;dotted.code&gt;]</code> part. The GraphQL update rejects file-type fields — use REST for any screen with an upload. Scalar-only updates work over either transport.</li></ol><p>Validation is <strong>server-side</strong> from each field&#39;s own rule (not trusted from the client) — a bad value returns <code>422</code> with the offending field; show it inline.</p><h2 id="status-codes-to-handle" tabindex="-1">Status codes to handle <a class="header-anchor" href="#status-codes-to-handle" aria-label="Permalink to &quot;Status codes to handle&quot;">​</a></h2><p><code>200</code> read/update OK · <code>400</code> missing <code>slug</code> or a key escaping the slug · <code>401</code> unauthenticated · <code>403</code> permission · <code>422</code> field validation failed (or a file field sent over GraphQL — use REST).</p>',9))])}const b=r(h,[["render",g]]);export{k as __pageData,b as default};
